namespace KuroWindows.Capture.Gen2;

internal static class Gen2Shaders
{
	public const string ConvertBgraToNv12 = "\r\nTexture2D<float3> Input : register(t0);\r\nRWTexture2D<unorm float>  OutY  : register(u0);\r\nRWTexture2D<unorm float2> OutUV : register(u1);\r\nSamplerState LinearSampler : register(s0);\r\n\r\n// BT.709 RGB->YUV rows\r\nstatic const float3 YR = {  0.2126,  0.7152,  0.0722 };\r\nstatic const float3 UR = { -0.1146, -0.3854,  0.5    };\r\nstatic const float3 VR = {  0.5,    -0.4542, -0.0458 };\r\n// limited (video) range\r\nstatic const float RANGE_Y   = 219.0 / 255.0;\r\nstatic const float OFFSET_Y  = 16.0 / 255.0;\r\nstatic const float RANGE_UV  = 224.0 / 255.0;\r\nstatic const float OFFSET_UV = 0.5 / 255.0 + 0.5;\r\n\r\n[numthreads(16, 16, 1)]\r\nvoid main(uint3 P : SV_DispatchThreadID)\r\n{\r\n    uint4 Pos4 = P.xyxy * 2 + uint4(0, 0, 1, 1);\r\n\r\n    float2 InSize;\r\n    Input.GetDimensions(InSize.x, InSize.y);\r\n\r\n    float2 ColorPos = float2(Pos4.xy) / InSize;\r\n    float3 C0 = Input.SampleLevel(LinearSampler, ColorPos, 0, int2(0, 1));\r\n    float3 C1 = Input.SampleLevel(LinearSampler, ColorPos, 0, int2(1, 1));\r\n    float3 C = lerp(C0, C1, 0.5);\r\n\r\n    OutUV[P.xy] = float2(dot(UR, C), dot(VR, C)) * RANGE_UV + OFFSET_UV;\r\n\r\n    OutY[Pos4.xy] = dot(YR, Input[Pos4.xy]) * RANGE_Y + OFFSET_Y;\r\n    OutY[Pos4.zy] = dot(YR, Input[Pos4.zy]) * RANGE_Y + OFFSET_Y;\r\n    OutY[Pos4.xw] = dot(YR, Input[Pos4.xw]) * RANGE_Y + OFFSET_Y;\r\n    OutY[Pos4.zw] = dot(YR, Input[Pos4.zw]) * RANGE_Y + OFFSET_Y;\r\n}\r\n";

	public const string BlendCursorOntoMailbox = "\r\nTexture2D<float4> Cursor : register(t0);\r\nRWTexture2D<uint> Mailbox : register(u0);\r\n\r\ncbuffer CursorPlacement : register(b0)\r\n{\r\n    int2 TopLeft;      // cursor rect origin in mailbox pixels\r\n    int2 CursorSize;   // cursor sprite dimensions\r\n    int2 MailboxSize;  // mailbox dimensions (clip guard)\r\n    int2 _pad;\r\n};\r\n\r\nstatic uint PackToBGRA(float3 Color)\r\n{\r\n    const uint3 Pack = { 1 << 16, 1 << 8, 1 };\r\n    return dot(uint3(saturate(Color.rgb) * 255 + 0.5), Pack) | 0xff000000;\r\n}\r\n\r\nstatic float3 UnpackBGRA(uint Value)\r\n{\r\n    return float3((Value >> 16) & 0xff, (Value >> 8) & 0xff, Value & 0xff) / 255.0;\r\n}\r\n\r\n[numthreads(8, 8, 1)]\r\nvoid main(uint3 P : SV_DispatchThreadID)\r\n{\r\n    if ((int)P.x >= CursorSize.x || (int)P.y >= CursorSize.y)\r\n    {\r\n        return;\r\n    }\r\n\r\n    int2 Dest = TopLeft + int2(P.xy);\r\n    if (Dest.x < 0 || Dest.y < 0 || Dest.x >= MailboxSize.x || Dest.y >= MailboxSize.y)\r\n    {\r\n        return;\r\n    }\r\n\r\n    float4 Src = Cursor[P.xy]; // straight-alpha BGRA sprite (DrawIconEx output)\r\n    if (Src.a <= 0.0)\r\n    {\r\n        return;\r\n    }\r\n\r\n    float3 Background = UnpackBGRA(Mailbox[uint2(Dest)]);\r\n    float3 Blended = lerp(Background, Src.rgb, Src.a);\r\n    Mailbox[uint2(Dest)] = PackToBGRA(Blended);\r\n}\r\n";
}
